     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import org.slf4j.Logger;
     6	import org.slf4j.LoggerFactory;
     7	
     8	import java.sql.Connection;
     9	import java.sql.SQLException;
    10	import java.sql.Statement;
    11	
    12	public class DatabaseConfig {
    13	    private static final Logger logger = LoggerFactory.getLogger(DatabaseConfig.class);
    14	    private static HikariDataSource dataSource;
    15	
    16	    public static void initializeDatabase() {
    17	        String dbUrl = System.getenv("DB_URL");
    18	        String dbUser = System.getenv("DB_USER");
    19	        String dbPassword = System.getenv("DB_PASSWORD");
    20	
    21	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    22	            throw new IllegalStateException("Variáveis de ambiente DB_URL, DB_USER e DB_PASSWORD são obrigatórias");
    23	        }
    24	
    25	        HikariConfig config = new HikariConfig();
    26	        config.setJdbcUrl(dbUrl);
    27	        config.setUsername(dbUser);
    28	        config.setPassword(dbPassword);
    29	        config.setMaximumPoolSize(10);
    30	        config.setMinimumIdle(2);
    31	        config.setConnectionTimeout(30000);
    32	        config.setIdleTimeout(600000);
    33	        config.setMaxLifetime(1800000);
    34	
    35	        dataSource = new HikariDataSource(config);
    36	        logger.info("Pool de conexões inicializado");
    37	
    38	        createSchemaIfNotExists();
    39	    }
    40	
    41	    public static Connection getConnection() throws SQLException {
    42	        return dataSource.getConnection();
    43	    }
    44	
    45	    private static void createSchemaIfNotExists() {
    46	        try (Connection conn = dataSource.getConnection();
    47	             Statement stmt = conn.createStatement()) {
    48	
    49	            String sql = """
    50	                CREATE TABLE IF NOT EXISTS rooms (
    51	                    number INT PRIMARY KEY,
    52	                    type VARCHAR(20) NOT NULL,
    53	                    capacity INT NOT NULL,
    54	                    nightly_rate NUMERIC(10, 2) NOT NULL
    55	                );
    56	
    57	                CREATE TABLE IF NOT EXISTS reservations (
    58	                    id BIGSERIAL PRIMARY KEY,
    59	                    room_number INT NOT NULL REFERENCES rooms(number),
    60	                    guest_name VARCHAR(255) NOT NULL,
    61	                    guest_email VARCHAR(255) NOT NULL,
    62	                    guest_cpf VARCHAR(14) NOT NULL,
    63	                    check_in DATE NOT NULL,
    64	                    check_out DATE NOT NULL,
    65	                    guests INT NOT NULL,
    66	                    rate_plan VARCHAR(20) NOT NULL,
    67	                    nights BIGINT NOT NULL,
    68	                    subtotal NUMERIC(10, 2) NOT NULL,
    69	                    discount NUMERIC(10, 2) NOT NULL,
    70	                    total NUMERIC(10, 2) NOT NULL,
    71	                    status VARCHAR(20) NOT NULL,
    72	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    73	                    refund NUMERIC(10, 2),
    74	                    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    75	                );
    76	
    77	                CREATE TABLE IF NOT EXISTS messages (
    78	                    id BIGSERIAL PRIMARY KEY,
    79	                    channel VARCHAR(50) NOT NULL,
    80	                    "to" VARCHAR(255) NOT NULL,
    81	                    subject VARCHAR(255) NOT NULL,
    82	                    body TEXT NOT NULL,
    83	                    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    84	                );
    85	
    86	                CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations(room_number);
    87	                CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status);
    88	                CREATE INDEX IF NOT EXISTS idx_reservations_check_in ON reservations(check_in);
    89	                """;
    90	
    91	            stmt.execute(sql);
    92	            logger.info("Schema criado com sucesso");
    93	
    94	            insertInitialRooms();
    95	
    96	        } catch (SQLException e) {
    97	            logger.error("Erro ao criar schema", e);
    98	            throw new RuntimeException(e);
    99	        }
   100	    }
   101	
   102	    private static void insertInitialRooms() {
   103	        try (Connection conn = dataSource.getConnection();
   104	             Statement stmt = conn.createStatement()) {
   105	
   106	            String checkSql = "SELECT COUNT(*) as cnt FROM rooms";
   107	            var rs = stmt.executeQuery(checkSql);
   108	            rs.next();
   109	            if (rs.getInt("cnt") == 0) {
   110	                String insertSql = """
   111	                    INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
   112	                    (101, 'STANDARD', 2, 249.90),
   113	                    (102, 'STANDARD', 2, 249.90),
   114	                    (201, 'DELUXE', 3, 389.90),
   115	                    (202, 'DELUXE', 3, 389.90),
   116	                    (301, 'SUITE', 4, 579.90);
   117	                    """;
   118	                stmt.execute(insertSql);
   119	                logger.info("Quartos iniciais inseridos");
   120	            }
   121	        } catch (SQLException e) {
   122	            logger.error("Erro ao inserir quartos iniciais", e);
   123	            throw new RuntimeException(e);
   124	        }
   125	    }
   126	}
