    18	public class ReportController {
    19	    private static final Logger logger = LoggerFactory.getLogger(ReportController.class);
    20	    private static final ReservationRepository reservationRepository = new ReservationRepository();
    21	    private static final RoomRepository roomRepository = new RoomRepository();
    22	
    23	    public static void routes(Javalin app) {
    24	        app.get("/reports/occupancy", ctx -> {
    25	            try {
    26	                String dateStr = ctx.queryParam("date");
    27	                if (dateStr == null) {
    28	                    ctx.status(400);
    29	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'date' é obrigatório"));
    30	                    return;
    31	                }
    32	
    33	                LocalDate date = DateUtil.parseIsoDate(dateStr);
    34	                List<Reservation> occupancy = reservationRepository.findOccupancyByDate(date);
    35	
    36	                StringBuilder csv = new StringBuilder();
    37	                csv.append("room,type,reservation,check_in,check_out\n");
    38	
    39	                for (Reservation r : occupancy) {
    40	                    csv.append(String.format("%d,%s,%d,%s,%s\n",
    41	                        r.roomNumber,
    42	                        getQuartoType(r.roomNumber),
    43	                        r.id,
    44	                        DateUtil.formatIsoDate(r.checkIn),
    45	                        DateUtil.formatIsoDate(r.checkOut)));
    46	                }
    47	
    48	                csv.append(String.format("total,%d/5", occupancy.size()));
    49	
    50	                ctx.contentType("text/csv;charset=utf-8");
    51	                ctx.result(csv.toString());
    52	            } catch (Exception e) {
    53	                logger.error("Erro ao gerar relatório de ocupação", e);
    54	                ctx.status(400);
    55	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Formato de data inválido"));
    56	            }
    57	        });
    58	
    59	        app.get("/reports/revenue", ctx -> {
    60	            try {
    61	                String monthStr = ctx.queryParam("month");
    62	                if (monthStr == null) {
    63	                    ctx.status(400);
    64	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'month' é obrigatório"));
    65	                    return;
    66	                }
    67	
    68	                YearMonth month = DateUtil.parseYearMonth(monthStr);
    69	                List<Reservation> revenue = reservationRepository.findByMonthWithPayment(month);
    70	
    71	                StringBuilder csv = new StringBuilder();
    72	                csv.append("reservation,room,check_in,check_out,status,amount\n");
    73	
    74	                double total = 0;
    75	                for (Reservation r : revenue) {
    76	                    double amount = r.amountPaid - (r.refund != null ? r.refund : 0);
    77	                    csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
    78	                        r.id,
    79	                        r.roomNumber,
    80	                        DateUtil.formatIsoDate(r.checkIn),
    81	                        DateUtil.formatIsoDate(r.checkOut),
    82	                        r.status.toString(),
    83	                        amount));
    84	                    total += amount;
    85	                }
    86	
    87	                csv.append(String.format("total,%.2f", total));
    88	
    89	                ctx.contentType("text/csv;charset=utf-8");
    90	                ctx.result(csv.toString());
    91	            } catch (Exception e) {
    92	                logger.error("Erro ao gerar relatório financeiro", e);
    93	                ctx.status(400);
    94	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Formato de mês inválido (use YYYY-MM)"));
    95	            }
    96	        });
    97	    }
    98	
    99	    static class ErrorResponse {
   100	        public String error;
   101	        public String message;
   102	
   103	        ErrorResponse(String error, String message) {
   104	            this.error = error;
   105	            this.message = message;
   106	        }
   107	    }
   108	
   109	    private static String getQuartoType(int roomNumber) {
   110	        return switch (roomNumber) {
   111	            case 101, 102 -> "STANDARD";
   112	            case 201, 202 -> "DELUXE";
   113	            case 301 -> "SUITE";
   114	            default -> "UNKNOWN";
   115	        };
   116	    }
   117	}
