    24	    public static void routes(Javalin app) {
    25	        app.post("/reservations", ctx -> {
    26	            try {
    27	                JsonNode body = mapper.readTree(ctx.body());
    28	
    29	                // Validar campos obrigatórios
    30	                if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
    31	                    !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
    32	                    !body.has("guests") || !body.has("ratePlan")) {
    33	                    ctx.status(400);
    34	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Campos obrigatórios faltando"));
    35	                    return;
    36	                }
    37	
    38	                try {
    39	                    int roomNumber = body.get("roomNumber").asInt();
    40	                    String guestName = body.get("guestName").asText();
    41	                    String guestEmail = body.get("guestEmail").asText();
    42	                    String guestCpf = body.get("guestCpf").asText();
    43	                    LocalDate checkIn = DateUtil.parseIsoDate(body.get("checkIn").asText());
    44	                    LocalDate checkOut = DateUtil.parseIsoDate(body.get("checkOut").asText());
    45	                    int guests = body.get("guests").asInt();
    46	                    RatePlan ratePlan = RatePlan.valueOf(body.get("ratePlan").asText());
    47	
    48	                    Reservation reservation = service.createReservation(roomNumber, guestName, guestEmail,
    49	                                                                        guestCpf, checkIn, checkOut, guests, ratePlan);
    50	                    ctx.status(201);
    51	                    ctx.json(reservation);
    52	                } catch (IllegalArgumentException e) {
    53	                    ctx.status(400);
    54	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "Formato de datas inválido ou plano de tarifa desconhecido"));
    55	                }
    56	            } catch (Exception e) {
    57	                logger.error("Erro ao processar JSON", e);
    58	                ctx.status(400);
    59	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Corpo da requisição inválido"));
    60	            }
    61	        });
    62	
    63	        app.get("/reservations/:id", ctx -> {
    64	            try {
    65	                long id = Long.parseLong(ctx.pathParam("id"));
