    18	        String dbUser = System.getenv("DB_USER");
    19	        String dbPassword = System.getenv("DB_PASSWORD");
    20	
    21	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    22	            throw new IllegalStateException("Variáveis de ambiente DB_URL, DB_USER e DB_PASSWORD são obrigatórias");
