    24	
    25	        HikariConfig config = new HikariConfig();
    26	        config.setJdbcUrl(dbUrl);
    27	        config.setUsername(dbUser);
    28	        config.setPassword(dbPassword);
    29	        config.setMaximumPoolSize(10);
    30	        config.setMinimumIdle(2);
    31	        config.setConnectionTimeout(30000);
    32	        config.setIdleTimeout(600000);
    33	        config.setMaxLifetime(1800000);
    34	
    35	        dataSource = new HikariDataSource(config);
