    45	    private static void createSchemaIfNotExists() {
    46	        try (Connection conn = dataSource.getConnection();
    47	             Statement stmt = conn.createStatement()) {
    48	
    49	            String sql = """
    50	                CREATE TABLE IF NOT EXISTS rooms (
    51	                    number INT PRIMARY KEY,
    52	                    type VARCHAR(20) NOT NULL,
    53	                    capacity INT NOT NULL,
    54	                    nightly_rate NUMERIC(10, 2) NOT NULL
    55	                );
    56	
    57	                CREATE TABLE IF NOT EXISTS reservations (
    58	                    id BIGSERIAL PRIMARY KEY,
    59	                    room_number INT NOT NULL REFERENCES rooms(number),
    60	                    guest_name VARCHAR(255) NOT NULL,
    61	                    guest_email VARCHAR(255) NOT NULL,
    62	                    guest_cpf VARCHAR(14) NOT NULL,
    63	                    check_in DATE NOT NULL,
    64	                    check_out DATE NOT NULL,
    65	                    guests INT NOT NULL,
