    79	                    channel VARCHAR(50) NOT NULL,
    80	                    "to" VARCHAR(255) NOT NULL,
    81	                    subject VARCHAR(255) NOT NULL,
    82	                    body TEXT NOT NULL,
    83	                    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    84	                );
    85	
    86	                CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations(room_number);
    87	                CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status);
    88	                CREATE INDEX IF NOT EXISTS idx_reservations_check_in ON reservations(check_in);
    89	                """;
    90	
    91	            stmt.execute(sql);
    92	            logger.info("Schema criado com sucesso");
    93	
    94	            insertInitialRooms();
    95	
    96	        } catch (SQLException e) {
    97	            logger.error("Erro ao criar schema", e);
    98	            throw new RuntimeException(e);
    99	        }
   100	    }
