    81	        String nightsLabel = reservation.nights == 1 ? "1 diária" : reservation.nights + " diárias";
    82	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
    83	            DateUtil.formatBrDate(reservation.checkIn),
    84	            DateUtil.formatBrDate(reservation.checkOut),
    85	            nightsLabel));
    86	
    87	        sb.append(String.format("Diárias: %s%n", MoneyUtil.formatBr(reservation.subtotal)));
    88	
    89	        if (reservation.discount > 0) {
    90	            sb.append(String.format("Desconto: %s%n", MoneyUtil.formatBr(reservation.discount)));
    91	        }
    92	
    93	        sb.append(String.format("Total: %s", MoneyUtil.formatBr(reservation.total)));
    94	
    95	        return sb.toString();
    96	    }
    97	
    98	    private String formatCpf(String cpf) {
    99	        if (cpf.length() != 11) return cpf;
   100	        return String.format("%s.%s.%s-%s",
   101	            cpf.substring(0, 3),
   102	            cpf.substring(3, 6),
   103	            cpf.substring(6, 9),
   104	            cpf.substring(9));
   105	    }
