    15	public class ReservationService {
    16	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
    17	    private final ReservationRepository reservationRepository = new ReservationRepository();
    18	    private final RoomRepository roomRepository = new RoomRepository();
    19	    private final NotificationService notificationService = new NotificationService();
