   106	        }
   107	
   108	        reservation.status = ReservationStatus.CONFIRMED;
   109	        reservation.amountPaid = MoneyUtil.round(amountPaid);
   110	        reservationRepository.save(reservation);
   111	
   112	        // Enviar notificações
