    15	public class ReservationService {
    16	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
    17	    private final ReservationRepository reservationRepository = new ReservationRepository();
    18	    private final RoomRepository roomRepository = new RoomRepository();
    19	    private final NotificationService notificationService = new NotificationService();
    20	
    21	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    22	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    23	        // Validações
    24	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
    25	        if (room.isEmpty()) {
    26	            throw new ApiException("ROOM_NOT_FOUND", "Quarto não encontrado", 404);
    27	        }
    28	
    29	        if (guests < 1) {
    30	            throw new ApiException("INVALID_REQUEST", "Quantidade de hóspedes deve ser maior que zero", 400);
    31	        }
    32	
    33	        if (guests > room.get().capacity) {
    34	            throw new ApiException("CAPACITY_EXCEEDED", "Quarto não comporta esta quantidade de hóspedes", 422);
    35	        }
    36	
    37	        if (!checkOut.isAfter(checkIn)) {
    38	            throw new ApiException("INVALID_REQUEST", "Data de saída deve ser após a data de entrada", 400);
    39	        }
    40	
    41	        // Verificar disponibilidade
    42	        var conflictingReservations = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
    43	        if (!conflictingReservations.isEmpty()) {
    44	            throw new ApiException("ROOM_UNAVAILABLE", "Quarto não está disponível para o período solicitado", 409);
    45	        }
    46	
    47	        // Calcular preços
    48	        long nights = ChronoUnit.DAYS.between(checkIn, checkOut);
    49	        Room r = room.get();
    50	
    51	        double subtotal = 0;
    52	        LocalDate date = checkIn;
    53	        while (!date.equals(checkOut)) {
    54	            double dailyRate = r.nightlyRate;
    55	            if (DateUtil.isHighSeason(date)) {
    56	                dailyRate = MoneyUtil.applyPercentage(dailyRate, 20);
    57	            }
    58	            dailyRate = MoneyUtil.round(dailyRate);
    59	            subtotal += dailyRate;
    60	            date = date.plusDays(1);
    61	        }
    62	        subtotal = MoneyUtil.round(subtotal);
    63	
    64	        double discount = 0;
    65	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    66	            discount = MoneyUtil.calculateDiscount(subtotal, 15);
    67	        }
    68	
    69	        double total = MoneyUtil.round(subtotal - discount);
    70	
    71	        Reservation reservation = new Reservation(
    72	            0,
    73	            roomNumber,
    74	            guestName,
    75	            guestEmail,
    76	            guestCpf,
    77	            checkIn,
    78	            checkOut,
    79	            guests,
    80	            ratePlan,
    81	            nights,
    82	            subtotal,
    83	            discount,
    84	            total,
    85	            ReservationStatus.PENDING,
    86	            0,
    87	            null
    88	        );
    89	
    90	        return reservationRepository.save(reservation);
    91	    }
