    97	    public Reservation confirmReservation(long id, double amountPaid) {
    98	        Optional<Reservation> opt = reservationRepository.findById(id);
    99	        if (opt.isEmpty()) {
   100	            throw new ApiException("RESERVATION_NOT_FOUND", "Reserva não encontrada", 404);
   101	        }
   102	
   103	        Reservation reservation = opt.get();
   104	        if (reservation.status != ReservationStatus.PENDING) {
   105	            throw new ApiException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas", 409);
   106	        }
   107	
   108	        reservation.status = ReservationStatus.CONFIRMED;
   109	        reservation.amountPaid = MoneyUtil.round(amountPaid);
   110	        reservationRepository.save(reservation);
   111	
   112	        // Enviar notificações
   113	        notificationService.sendGuestConfirmationEmail(reservation);
   114	        notificationService.sendHousekeepingNotification(reservation);
   115	        notificationService.sendFinanceNotificationConfirmation(reservation);
   116	
   117	        return reservation;
   118	    }
