   120	    public Reservation cancelReservation(long id) {
   121	        Optional<Reservation> opt = reservationRepository.findById(id);
   122	        if (opt.isEmpty()) {
   123	            throw new ApiException("RESERVATION_NOT_FOUND", "Reserva não encontrada", 404);
   124	        }
   125	
   126	        Reservation reservation = opt.get();
   127	        if (reservation.status == ReservationStatus.CHECKED_OUT ||
   128	            reservation.status == ReservationStatus.CANCELLED) {
   129	            throw new ApiException("OPERATION_NOT_ALLOWED", "Não é possível cancelar esta reserva", 409);
   130	        }
   131	
   132	        boolean wasConfirmed = reservation.status == ReservationStatus.CONFIRMED;
   133	        double refundAmount = 0;
   134	
   135	        if (wasConfirmed) {
   136	            if (reservation.ratePlan == RatePlan.STANDARD) {
   137	                refundAmount = reservation.amountPaid;
   138	            }
   139	            // NON_REFUNDABLE não retorna nada
   140	        }
   141	        // PENDING não tem o que devolver
   142	
   143	        reservation.status = ReservationStatus.CANCELLED;
   144	        if (refundAmount > 0) {
   145	            reservation.refund = MoneyUtil.round(refundAmount);
   146	        }
   147	
   148	        reservationRepository.save(reservation);
   149	
   150	        // Enviar notificações apenas se era confirmada
   151	        if (wasConfirmed) {
   152	            notificationService.sendHousekeepingCancellationNotification(reservation);
   153	            if (refundAmount > 0) {
   154	                notificationService.sendFinanceNotificationCancellation(reservation, refundAmount);
   155	            }
   156	        }
   157	
