     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.NumberFormat;
     6	import java.util.Locale;
     7	
     8	public class MoneyUtil {
     9	    private static final int SCALE = 2;
    10	
    11	    public static double round(double value) {
    12	        BigDecimal bd = new BigDecimal(value);
    13	        return bd.setScale(SCALE, RoundingMode.HALF_EVEN).doubleValue();
    14	    }
    15	
    16	    public static double applyPercentage(double value, double percentage) {
    17	        BigDecimal bd = new BigDecimal(value);
    18	        BigDecimal multiplier = new BigDecimal(1 + percentage / 100.0);
    19	        return bd.multiply(multiplier).setScale(SCALE, RoundingMode.HALF_EVEN).doubleValue();
    20	    }
    21	
    22	    public static double calculateDiscount(double subtotal, double discountPercentage) {
    23	        BigDecimal bd = new BigDecimal(subtotal);
    24	        BigDecimal percentage = new BigDecimal(discountPercentage / 100.0);
    25	        return bd.multiply(percentage).setScale(SCALE, RoundingMode.HALF_EVEN).doubleValue();
    26	    }
    27	
    28	    public static String formatBr(double value) {
    29	        NumberFormat nf = NumberFormat.getInstance(new Locale("pt", "BR"));
    30	        nf.setMinimumFractionDigits(2);
    31	        nf.setMaximumFractionDigits(2);
    32	        return "R$ " + nf.format(value);
    33	    }
    34	
    35	    public static String formatJson(double value) {
    36	        return String.format("%.2f", value);
    37	    }
    38	}
