     3	import java.time.LocalDate;
     4	import java.time.YearMonth;
     5	import java.time.format.DateTimeFormatter;
     6	
     7	public class DateUtil {
     8	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ISO_LOCAL_DATE;
     9	    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    10	
    11	    public static LocalDate parseIsoDate(String dateStr) {
    12	        return LocalDate.parse(dateStr, ISO_DATE);
    13	    }
    14	
    15	    public static String formatBrDate(LocalDate date) {
    16	        return date.format(BR_DATE);
    17	    }
    18	
    19	    public static String formatIsoDate(LocalDate date) {
    20	        return date.format(ISO_DATE);
    21	    }
    22	
    23	    public static YearMonth parseYearMonth(String yearMonthStr) {
    24	        return YearMonth.parse(yearMonthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
    25	    }
    26	
    27	    public static boolean isHighSeason(LocalDate date) {
    28	        int month = date.getMonthValue();
    29	        int day = date.getDayOfMonth();
    30	        int year = date.getYear();
    31	
    32	        // Julho inteiro
    33	        if (month == 7) return true;
    34	
    35	        // 15 de dezembro a 28 de fevereiro
    36	        LocalDate dateToCheck = LocalDate.of(year, month, day);
    37	        LocalDate seasonStart = LocalDate.of(year, 12, 15);
    38	        LocalDate seasonEnd = LocalDate.of(year + 1, 2, 28);
    39	
    40	        if (dateToCheck.isBefore(seasonStart)) {
    41	            // Se é antes de 15 de dezembro, verifica se é do ano anterior
    42	            seasonStart = LocalDate.of(year - 1, 12, 15);
    43	            seasonEnd = LocalDate.of(year, 2, 28);
    44	        }
    45	
    46	        return !dateToCheck.isBefore(seasonStart) && !dateToCheck.isAfter(seasonEnd);
    47	    }
    48	}
